import{_ as l,a0 as p,w as r,s as o,ao as c,I as i,x as n,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191006 How to Install and Configure VNC Server on Centos 8 - RHEL 8","title":"如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器","tag":"201910","desc":""},"relativePath":"201910/20191006 How to Install and Configure VNC Server on Centos 8 - RHEL 8.md","filePath":"[post].md"}'),d={name:"201910/20191006 How to Install and Configure VNC Server on Centos 8 - RHEL 8.md"};function h(u,s,g,C,k,v){const e=p("Link");return r(),o("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-centos-8-rhel-8-上安装和配置-vnc-服务器" tabindex="-1">如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器 <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安装和配置-vnc-服务器" aria-label="Permalink to “如何在 Centos 8 / RHEL 8 上安装和配置 VNC 服务器”">​</a></h1><p>VNC（<ruby>虚拟网络计算<rt>Virtual Network Computing</rt></ruby>）服务器是基于 GUI 的桌面共享平台，它可让你访问远程桌面计算机。在 Centos 8 和 RHEL 8 系统中，默认未安装 VNC 服务器，它需要手动安装。在本文中，我们将通过简单的分步指南，介绍如何在 Centos 8 / RHEL 8 上安装 VNC 服务器。</p><h3 id="在-centos-8-rhel-8-上安装-vnc-服务器的先决要求" tabindex="-1">在 Centos 8 / RHEL 8 上安装 VNC 服务器的先决要求 <a class="header-anchor" href="#在-centos-8-rhel-8-上安装-vnc-服务器的先决要求" aria-label="Permalink to “在 Centos 8 / RHEL 8 上安装 VNC 服务器的先决要求”">​</a></h3><p>要在你的系统中安装 VNC 服务器，请确保你的系统满足以下要求：</p><ul><li>CentOS 8 / RHEL 8</li><li>GNOME 桌面环境</li><li>root 用户权限</li><li>DNF / YUM 软件包仓库</li></ul><h3 id="在-centos-8-rhel-8-上安装-vnc-服务器的分步指导" tabindex="-1">在 Centos 8 / RHEL 8 上安装 VNC 服务器的分步指导 <a class="header-anchor" href="#在-centos-8-rhel-8-上安装-vnc-服务器的分步指导" aria-label="Permalink to “在 Centos 8 / RHEL 8 上安装 VNC 服务器的分步指导”">​</a></h3><h4 id="步骤-1-安装-gnome-桌面环境" tabindex="-1">步骤 1）安装 GNOME 桌面环境 <a class="header-anchor" href="#步骤-1-安装-gnome-桌面环境" aria-label="Permalink to “步骤 1）安装 GNOME 桌面环境”">​</a></h4><p>在 CentOS 8 / RHEL 8 中安装 VNC 服务器之前，请确保已安装了桌面环境（DE）。如果已经安装了 GNOME 桌面或安装了 GUI 支持，那么可以跳过此步骤。</p><p>在 CentOS 8 / RHEL 8 中，GNOME 是默认的桌面环境。如果你的系统中没有它，请使用以下命令进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf groupinstall &quot;workstation&quot;</span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>[root@linuxtechi ~]# dnf groupinstall &quot;Server with GUI</span></span></code></pre></div><p>成功安装上面的包后，请运行以下命令启用图形模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl set-default graphical</span></span></code></pre></div><p>现在重启系统，进入 GNOME 登录页面（LCTT 译注：你可以通过切换运行态来进入图形界面）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# reboot</span></span></code></pre></div><p>重启后，请取消注释 <code>/etc/gdm/custom.conf</code> 中的 <code>WaylandEnable=false</code>，以使通过 vnc 进行的远程桌面会话请求由 GNOME 桌面的 xorg 处理，来代替 Wayland 显示管理器。</p><p>注意： Wayland 是 GNOME 中的默认显示管理器 （GDM），并且未配置用于处理 X.org 等远程渲染的 API。</p><h4 id="步骤-2-安装-vnc-服务器-tigervnc-server" tabindex="-1">步骤 2）安装 VNC 服务器（tigervnc-server） <a class="header-anchor" href="#步骤-2-安装-vnc-服务器-tigervnc-server" aria-label="Permalink to “步骤 2）安装 VNC 服务器（tigervnc-server）”">​</a></h4><p>接下来，我们将安装 VNC 服务器，有很多 VNC 服务器可以选择，出于安装目的，我们将安装 <code>TigerVNC 服务器</code>。它是最受欢迎的 VNC 服务器之一，并且高性能还独立于平台，它使用户可以轻松地与远程计算机进行交互。</p><p>现在，使用以下命令安装 TigerVNC 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install tigervnc-server tigervnc-server-module -y</span></span></code></pre></div><h4 id="步骤-3-为本地用户设置-vnc-密码" tabindex="-1">步骤 3）为本地用户设置 VNC 密码 <a class="header-anchor" href="#步骤-3-为本地用户设置-vnc-密码" aria-label="Permalink to “步骤 3）为本地用户设置 VNC 密码”">​</a></h4><p>假设我们希望用户 <code>pkumar</code> 使用 VNC 进行远程桌面会话，然后切换到该用户并使用 <code>vncpasswd</code> 命令设置其密码，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# su - pkumar</span></span>
<span class="line"><span>[root@linuxtechi ~]$ vncpasswd</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>Verify:</span></span>
<span class="line"><span>Would you like to enter a view-only password (y/n)? n</span></span>
<span class="line"><span>A view-only password is not used</span></span>
<span class="line"><span>[root@linuxtechi ~]$</span></span>
<span class="line"><span>[root@linuxtechi ~]$ exit</span></span>
<span class="line"><span>logout</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步骤-4-设置-vnc-服务器配置文件" tabindex="-1">步骤 4）设置 VNC 服务器配置文件 <a class="header-anchor" href="#步骤-4-设置-vnc-服务器配置文件" aria-label="Permalink to “步骤 4）设置 VNC 服务器配置文件”">​</a></h4><p>下一步是配置 VNC 服务器配置文件。创建含以下内容的 <code>/etc/systemd/system/vncserver@.service</code>，以便为上面的本地用户 <code>pkumar</code> 启动 tigervnc-server 的服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# vim /etc/systemd/system/vncserver@.service</span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=Remote Desktop VNC Service</span></span>
<span class="line"><span>After=syslog.target network.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=forking</span></span>
<span class="line"><span>WorkingDirectory=/home/pkumar</span></span>
<span class="line"><span>User=pkumar</span></span>
<span class="line"><span>Group=pkumar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ExecStartPre=/bin/sh -c &#39;/usr/bin/vncserver -kill %i &gt; /dev/null 2&gt;&amp;1 || :&#39;</span></span>
<span class="line"><span>ExecStart=/usr/bin/vncserver -autokill %i</span></span>
<span class="line"><span>ExecStop=/usr/bin/vncserver -kill %i</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre></div><p>保存并退出文件，</p><p>注意：替换上面文件中的用户名为你自己的。</p><p>默认情况下，VNC 服务器在 tcp 端口 5900+n 上监听，其中 n 是显示端口号，如果显示端口号为 “1”，那么 VNC 服务器将在 TCP 端口 5901 上监听其请求。</p><h4 id="步骤-5-启动-vnc-服务并允许防火墙中的端口" tabindex="-1">步骤 5）启动 VNC 服务并允许防火墙中的端口 <a class="header-anchor" href="#步骤-5-启动-vnc-服务并允许防火墙中的端口" aria-label="Permalink to “步骤 5）启动 VNC 服务并允许防火墙中的端口”">​</a></h4><p>我将显示端口号设置为 1，因此请使用以下命令在显示端口号 “1” 上启动并启用 vnc 服务，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl daemon-reload</span></span>
<span class="line"><span>[root@linuxtechi ~]# systemctl start vncserver@:1.service</span></span>
<span class="line"><span>[root@linuxtechi ~]# systemctl enable vncserver@:1.service</span></span>
<span class="line"><span>Created symlink /etc/systemd/system/multi-user.target.wants/vncserver@:1.service → /etc/systemd/system/vncserver@.service.</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的 <code>netstat</code> 或 <code>ss</code> 命令来验证 VNC 服务器是否开始监听 5901 上的请求，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# netstat -tunlp | grep 5901</span></span>
<span class="line"><span>tcp        0      0 0.0.0.0:5901            0.0.0.0:*               LISTEN      8169/Xvnc</span></span>
<span class="line"><span>tcp6       0      0 :::5901                 :::*                    LISTEN      8169/Xvnc</span></span>
<span class="line"><span>[root@linuxtechi ~]# ss -tunlp | grep -i 5901</span></span>
<span class="line"><span>tcp   LISTEN  0       5                    0.0.0.0:5901           0.0.0.0:*      users:((&quot;Xvnc&quot;,pid=8169,fd=6))                    </span></span>
<span class="line"><span>tcp   LISTEN  0       5                       [::]:5901              [::]:*      users:((&quot;Xvnc&quot;,pid=8169,fd=7))                    </span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>使用下面的 <code>systemctl</code> 命令验证 VNC 服务器的状态，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl status vncserver@:1.service</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/vncserver-status-centos8-rhel8.jpg" alt="vncserver-status-centos8-rhel8"></p><p>上面命令的输出确认在 tcp 端口 5901 上成功启动了 VNC。使用以下命令在系统防火墙中允许 VNC 服务器端口 “5901”，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-port=5901/tcp</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --reload</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h4 id="步骤-6-连接到远程桌面会话" tabindex="-1">步骤 6）连接到远程桌面会话 <a class="header-anchor" href="#步骤-6-连接到远程桌面会话" aria-label="Permalink to “步骤 6）连接到远程桌面会话”">​</a></h4><p>现在，我们已经准备就绪，可以查看远程桌面连接是否正常工作。要访问远程桌面，请在 Windows / Linux 工作站中启动 VNC Viewer，然后输入 VNC 服务器的 IP 地址和端口号，然后按回车。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/VNC-Viewer-Windows10.jpg" alt="VNC-Viewer-Windows10"></p><p>接下来，它将询问你的 VNC 密码。输入你先前为本地用户创建的密码，然后单击 “OK” 继续。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/VNC-Viewer-Connect-CentOS8-RHEL8-VNC-Server.jpg" alt="VNC-Viewer-Connect-CentOS8-RHEL8-VNC-Server"></p><p>现在你可以看到远程桌面，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/VNC-Desktop-Screen-CentOS8.jpg" alt="VNC-Desktop-Screen-CentOS8"></p><p>就是这样，你已经在 Centos 8 / RHEL 8 中成功安装了 VNC 服务器。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>希望这篇在 Centos 8 / RHEL 8 上安装 VNC 服务器的分步指南为你提供了轻松设置 VNC 服务器并访问远程桌面的所有信息。请在下面的评论栏中提供你的意见和建议。下篇文章再见。谢谢再见！！！</p><hr>`,50)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/install-configure-vnc-server-centos8-rhel8/"},{default:t(()=>[...s[0]||(s[0]=[n("https://www.linuxtechi.com/install-configure-vnc-server-centos8-rhel8/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[n("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[n("geekpi",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const N=l(d,[["render",h]]);export{f as __pageData,N as default};
